package main

import "net/http"

func (s *server) index(w http.ResponseWriter, r *http.Request) {
	if r.URL.Path != "/" {
		http.NotFound(w, r)
		return
	}
	if r.Method != http.MethodGet {
		w.Header().Set("Allow", http.MethodGet)
		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		return
	}
	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	_, _ = w.Write([]byte(indexHTML))
}

const indexHTML = `<!doctype html>
<html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>MinIO API Tester</title><style>
:root{color-scheme:dark;--bg:#101318;--panel:#191d24;--line:#303641;--muted:#9099a8;--text:#edf1f7;--blue:#5a8cff;--green:#45c486;--red:#ff667a}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:14px/1.45 ui-monospace,SFMono-Regular,Menlo,monospace}header{padding:22px 28px;border-bottom:1px solid var(--line);background:#14171d}h1{margin:0 0 4px;font:700 21px/1.3 system-ui,sans-serif}header p{margin:0;color:var(--muted)}main{max-width:1180px;margin:auto;padding:24px}.presets{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:16px}button{border:1px solid var(--line);border-radius:7px;padding:9px 13px;background:#242a33;color:var(--text);cursor:pointer;font:inherit}button:hover{border-color:#596273}button:disabled{opacity:.55;cursor:wait}.preset strong{color:#82a5ff}.request-line{display:grid;grid-template-columns:120px 1fr 90px;gap:8px}select,input,textarea{width:100%;border:1px solid var(--line);border-radius:7px;background:#11151b;color:var(--text);padding:11px;font:inherit;outline:none}select:focus,input:focus,textarea:focus{border-color:var(--blue)}#send{border-color:var(--blue);background:var(--blue);color:white;font-weight:700}.grid{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-top:16px}.panel{min-width:0;overflow:hidden;border:1px solid var(--line);border-radius:10px;background:var(--panel)}.panel-title{display:flex;justify-content:space-between;align-items:center;min-height:46px;padding:0 14px;border-bottom:1px solid var(--line);font-family:system-ui,sans-serif;font-weight:650}.panel-body{padding:14px}label{display:block;margin:0 0 7px;color:var(--muted);font-size:12px;text-transform:uppercase;letter-spacing:.07em}textarea{min-height:145px;resize:vertical}#body{min-height:220px}.field+.field{margin-top:16px}.body-tools{display:flex;gap:14px;align-items:center;margin-bottom:9px;color:var(--muted)}.body-tools label{margin:0;text-transform:none;letter-spacing:0;cursor:pointer}.body-tools input{width:auto;margin-right:5px}#file{display:none;margin-bottom:10px;padding:8px}.response-meta{display:flex;gap:12px;color:var(--muted);font-weight:400}#status.ok{color:var(--green)}#status.error{color:var(--red)}pre{min-height:145px;max-height:330px;margin:0;overflow:auto;white-space:pre-wrap;overflow-wrap:anywhere;color:#cbd5e1}#response-body{min-height:220px}.hint{margin-top:14px;color:var(--muted);font:13px system-ui,sans-serif}code{color:#b8c9ff}@media(max-width:780px){main{padding:16px}.grid{grid-template-columns:1fr}.request-line{grid-template-columns:100px 1fr}.request-line button{grid-column:1/-1}}
</style></head><body><header><h1>MinIO API Tester</h1><p>Storage API 요청을 직접 만들고 응답을 확인합니다.</p></header><main>
<div class="presets" aria-label="요청 예제"><button class="preset" data-method="GET" data-url="/healthz"><strong>GET</strong> 상태 확인</button><button class="preset" data-method="GET" data-url="/objects"><strong>GET</strong> 객체 목록</button><button class="preset" data-method="PUT" data-url="/objects/hello.txt" data-body="Hello MinIO"><strong>PUT</strong> 객체 업로드</button><button class="preset" data-method="GET" data-url="/objects/hello.txt"><strong>GET</strong> 객체 다운로드</button><button class="preset" data-method="DELETE" data-url="/objects/hello.txt"><strong>DELETE</strong> 객체 삭제</button><button class="preset" data-method="GET" data-url="/metrics"><strong>GET</strong> 메트릭</button></div>
<form id="request-form"><div class="request-line"><select id="method" aria-label="HTTP method"><option>GET</option><option>PUT</option><option>POST</option><option>DELETE</option></select><input id="url" value="/objects" aria-label="Request URL" spellcheck="false"><button id="send" type="submit">Send</button></div><div class="grid">
<section class="panel"><div class="panel-title">Request</div><div class="panel-body"><div class="field"><label for="headers">Headers</label><textarea id="headers" spellcheck="false">Content-Type: text/plain</textarea></div><div class="field"><label>Body</label><div class="body-tools"><label><input type="radio" name="body-type" value="text" checked>Text</label><label><input type="radio" name="body-type" value="file">File</label></div><input id="file" type="file"><textarea id="body" spellcheck="false" placeholder="PUT/POST 요청 본문을 입력하세요."></textarea></div></div></section>
<section class="panel"><div class="panel-title"><span>Response</span><span class="response-meta"><span id="status">대기 중</span><span id="duration"></span></span></div><div class="panel-body"><div class="field"><label>Headers</label><pre id="response-headers">요청을 보내면 응답 헤더가 표시됩니다.</pre></div><div class="field"><label>Body</label><pre id="response-body">요청을 보내면 응답 본문이 표시됩니다.</pre></div></div></section>
</div></form><p class="hint">상대 경로는 현재 서버(<code id="origin"></code>)로 요청합니다. File 모드는 PUT/POST 업로드에 사용할 수 있습니다.</p></main>
<script>
const method=document.querySelector('#method'),url=document.querySelector('#url'),headersInput=document.querySelector('#headers'),bodyInput=document.querySelector('#body'),fileInput=document.querySelector('#file'),send=document.querySelector('#send'),status=document.querySelector('#status'),duration=document.querySelector('#duration'),responseHeaders=document.querySelector('#response-headers'),responseBody=document.querySelector('#response-body');document.querySelector('#origin').textContent=location.origin;
function parseHeaders(value){const headers=new Headers();value.split('\n').forEach(line=>{if(!line.trim())return;const split=line.indexOf(':');if(split<1)throw new Error('잘못된 헤더: '+line);headers.append(line.slice(0,split).trim(),line.slice(split+1).trim())});return headers}
function setBodyType(type){document.querySelector('input[name="body-type"][value="'+type+'"]').checked=true;const fileMode=type==='file';fileInput.style.display=fileMode?'block':'none';bodyInput.style.display=fileMode?'none':'block'}
document.querySelectorAll('input[name="body-type"]').forEach(input=>input.addEventListener('change',()=>setBodyType(input.value)));
document.querySelectorAll('.preset').forEach(button=>button.addEventListener('click',()=>{method.value=button.dataset.method;url.value=button.dataset.url;bodyInput.value=button.dataset.body||'';setBodyType('text')}));
document.querySelector('#request-form').addEventListener('submit',async event=>{event.preventDefault();send.disabled=true;status.className='';status.textContent='요청 중...';duration.textContent='';responseHeaders.textContent='';responseBody.textContent='';const started=performance.now();try{const headers=parseHeaders(headersInput.value),options={method:method.value,headers};if(method.value!=='GET'){const fileMode=document.querySelector('input[name="body-type"]:checked').value==='file';if(fileMode){if(!fileInput.files[0])throw new Error('업로드할 파일을 선택하세요.');options.body=fileInput.files[0];if(!headers.has('Content-Type'))headers.set('Content-Type',fileInput.files[0].type||'application/octet-stream')}else{options.body=bodyInput.value}}const response=await fetch(url.value,options);duration.textContent=Math.round(performance.now()-started)+' ms';status.textContent=response.status+' '+response.statusText;status.className=response.ok?'ok':'error';responseHeaders.textContent=Array.from(response.headers.entries()).map(item=>item[0]+': '+item[1]).join('\n')||'(응답 헤더 없음)';const type=response.headers.get('content-type')||'';if(type.includes('application/octet-stream')||type.includes('image/')){const blob=await response.blob();responseBody.textContent='[binary response] '+blob.size+' bytes'}else{responseBody.textContent=(await response.text())||'(응답 본문 없음)'}}catch(error){duration.textContent=Math.round(performance.now()-started)+' ms';status.textContent='요청 실패';status.className='error';responseBody.textContent=error.message}finally{send.disabled=false}});
</script></body></html>`
